body.script:
document.addEventListener('DOMContentLoaded', function () {
  const menuButton = document.querySelector('.navbar1_menu-button.w-nav-button');
  const navbarComponent = document.querySelector('.navbar1_component[theme="dark"]');
  const logoDark = document.querySelector('.navbar1_logo.is-dark');
  const logoLight = document.querySelector('.navbar1_logo.is-light');

  function toggleMenu() {
    if (menuButton.classList.contains('w--open')) {
      // When .w--open is added
      navbarComponent.style.color = 'white';
      logoLight.style.display = 'none';
      logoDark.style.display = 'block';
    } else {
      // When .w--open is removed
      navbarComponent.style.color = '#264247';
      logoLight.style.display = 'block';
      logoDark.style.display = 'none';
    }
  }

  // Initial check in case the .w--open class is already present
  toggleMenu();

  // Add event listener to detect changes in the class
  menuButton.addEventListener('click', toggleMenu);
});

// marquee power up
function attr(defaultVal, attrVal) {
  const defaultValType = typeof defaultVal;
  if (typeof attrVal !== "string" || attrVal.trim() === "") return defaultVal;
  if (attrVal === "true" && defaultValType === "boolean") return true;
  if (attrVal === "false" && defaultValType === "boolean") return false;
  if (isNaN(attrVal) && defaultValType === "string") return attrVal;
  if (!isNaN(attrVal) && defaultValType === "number") return +attrVal;
  return defaultVal;
}
// marquee component
$("[tr-marquee-element='component']").each(function (index) {
  let componentEl = $(this),
      panelEl = componentEl.find("[tr-marquee-element='panel']"),
      triggerHoverEl = componentEl.find("[tr-marquee-element='triggerhover']"),
      triggerClickEl = componentEl.find("[tr-marquee-element='triggerclick']");
  let speedSetting = attr(100, componentEl.attr("tr-marquee-speed")),
      verticalSetting = attr(false, componentEl.attr("tr-marquee-vertical")),
      reverseSetting = attr(false, componentEl.attr("tr-marquee-reverse")),
      scrollDirectionSetting = attr(false, componentEl.attr("tr-marquee-scrolldirection")),
      scrollScrubSetting = attr(false, componentEl.attr("tr-marquee-scrollscrub")),
      moveDistanceSetting = -100,
      timeScaleSetting = 1,
      pausedStateSetting = false;
  if (reverseSetting) moveDistanceSetting = 100;
  let marqueeTimeline = gsap.timeline({
    repeat: -1,
    onReverseComplete: () => marqueeTimeline
    .progress(1)
  });
  if (verticalSetting) {
    speedSetting = panelEl.first().height() / speedSetting;
    marqueeTimeline.fromTo(panelEl, { yPercent: 0 }, {
      yPercent: moveDistanceSetting,
      ease: "none",
      duration: speedSetting
    });
  } else {
    speedSetting = panelEl.first().width() / speedSetting;
    marqueeTimeline.fromTo(panelEl, { xPercent: 0 }, {
      xPercent: moveDistanceSetting,
      ease: "none",
      duration: speedSetting
    });
  }
  let scrubObject = { value: 1 };
  ScrollTrigger.create({
    trigger: "body",
    start: "top top",
    end: "bottom bottom",
    onUpdate: (self) => {
      if (!pausedStateSetting) {
        if (scrollDirectionSetting && timeScaleSetting !== self.direction) {
          timeScaleSetting = self.direction;
          marqueeTimeline.timeScale(self.direction);
        }
        if (scrollScrubSetting) {
          let v = self.getVelocity() * 0.006;
          v = gsap.utils.clamp(-60, 60, v);
          let scrubTimeline = gsap.timeline({
            onUpdate: () => marqueeTimeline.timeScale(
              scrubObject.value)
          });
          scrubTimeline.fromTo(scrubObject, { value: v }, {
            value: timeScaleSetting,
            duration: 0.5
          });
        }
      }
    }
  });

  function pauseMarquee(isPausing) {
    pausedStateSetting = isPausing;
    let pauseObject = { value: 1 };
    let pauseTimeline = gsap.timeline({
      onUpdate: () => marqueeTimeline.timeScale(pauseObject
                                                .value)
    });
    if (isPausing) {
      pauseTimeline.fromTo(pauseObject, { value: timeScaleSetting }, {
        value: 0,
        duration: 0.5
      });
      triggerClickEl.addClass("is-paused");
    } else {
      pauseTimeline.fromTo(pauseObject, { value: 0 }, {
        value: timeScaleSetting,
        duration: 0.5
      });
      triggerClickEl.removeClass("is-paused");
    }
  }
  if (window.matchMedia("(pointer: fine)").matches) {
    triggerHoverEl.on("mouseenter", () => pauseMarquee(true));
    triggerHoverEl.on("mouseleave", () => pauseMarquee(false));
  }
  triggerClickEl.on("click", function () {
    !$(this).hasClass("is-paused") ? pauseMarquee(true) : pauseMarquee(false);
  });
});

// Function to disable the first option of all select elements
function disableFirstOption() {
  const selects = document.querySelectorAll('select');
  selects.forEach(select => {
    const firstOption = select.options[0];
    if (firstOption) {
      firstOption.disabled = true;  // Disable the first option
    }

    // Change color of selected option
    select.addEventListener('change', function () {
      if (this.value) {
        this.style.color = 'var(--kafene--gray--800)'; // Set to gray-800 when selected
      } else {
        this.style.color = 'var(--kafene--gray--500)'; // Reset to gray-500 when no selection
      }
    });
  });
}

// Call the function on page load
disableFirstOption();

